// Electron Forge configuration for building and packaging the coda desktop app.

// #endregion 🔖Header

// #region 🔖Configuration
// [🔬coda🖱️desktop⚙️forgeconfig🔖configuration](semiorepo://p/r/coda/b/u/desktop/f/forge.config.ts/s/Configuration)
// Electron Forge build configuration for the coda desktop application.
// Configuration MUST define packager, makers, and plugins for Electron Forge.

import type { ForgeConfig } from "@electron-forge/shared-types";
import { MakerSquirrel } from "@electron-forge/maker-squirrel";
import { MakerZIP } from "@electron-forge/maker-zip";
import { MakerDeb } from "@electron-forge/maker-deb";
import { MakerRpm } from "@electron-forge/maker-rpm";
import { VitePlugin } from "@electron-forge/plugin-vite";
import { FusesPlugin } from "@electron-forge/plugin-fuses";
import { FuseV1Options, FuseVersion } from "@electron/fuses";

/**
 * Electron Forge configuration with Vite plugin and security fuses.
// [🔬coda🖱️desktop⚙️forgeconfig🔖configuration🪨config](semiorepo://p/r/coda/b/u/desktop/f/forge.config.ts/s/Configuration/d/i/config)
 * Config MUST include VitePlugin with main, preload, and renderer entries.
 **/
const config: ForgeConfig = {
  packagerConfig: {
    asar: true,
  },
  rebuildConfig: {},
  makers: [new MakerSquirrel({}), new MakerZIP({}, ["darwin"]), new MakerRpm({}), new MakerDeb({})],
  plugins: [
    new VitePlugin({
      build: [
        {
          entry: "main.ts",
          config: "vite.main.config.ts",
          target: "main",
        },
        {
          entry: "preload.ts",
          config: "vite.preload.config.ts",
          target: "preload",
        },
      ],
      renderer: [
        {
          name: "main_window",
          config: "vite.renderer.config.ts",
        },
      ],
    }),

    new FusesPlugin({
      version: FuseVersion.V1,
      [FuseV1Options.RunAsNode]: false,
      [FuseV1Options.EnableCookieEncryption]: true,
      [FuseV1Options.EnableNodeOptionsEnvironmentVariable]: false,
      [FuseV1Options.EnableNodeCliInspectArguments]: false,
      [FuseV1Options.EnableEmbeddedAsarIntegrityValidation]: true,
      [FuseV1Options.OnlyLoadAppFromAsar]: true,
    }),
  ],
};

export default config;
// #endregion 🔖Configuration

